// FortreeCity_House4 (zone 141): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0160_room_FortreeCity_House4.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch7
#include "hoenn_story.inc"  // ch7

    ScriptEntry Script_1
    ScriptEntry FH4_Boy  // 2: FortreeCity_House4_EventScript_Boy  // story:
    ScriptEntry FH4_Wingull  // 3: FortreeCity_House4_EventScript_Wingull  // story:
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    ParentActorMsg MSGFILE_SCRIPT, 0, 0, 0
    LastKeyWait
    ActorMsgClose
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch7, ch7 agent 2026-10-07; Sapphire data/maps/FortreeCity_House4/scripts.inc; generators must keep
// everything from this line on). Scripts 2-3, text lines 1-6 (line 0 is the generator's woman). The boy (uid 2) and the
// Wingull (uid 3, hidden by FLAG_HIDE_WINGULL_FORTREE_HOUSE while it is away) are in data/story/ch7.json. The Mossdeep end
// (Ch9: MossdeepCity_House2 clears FLAG_HIDE_WINGULL_FORTREE_HOUSE and sets FLAG_WINGULL_DELIVERED_MAIL) is Ch9's.
// Room tiles = Sapphire tiles + (1,1).
#include "scenes/ch7_lib.inc"
#define T_GoBird 1
#define T_OnErrand 2
#define T_Welcome 3
#define T_FriendsFar 4
#define T_Wingull 5
#define T_BagFull 6
#define FH4_BOY 2
#define FH4_WINGULL 3

FH4_Boy:                                            // FortreeCity_House4_EventScript_Boy (lockall)
    c7_talk
    h_goto_if_set FLAG_RECEIVED_MENTAL_HERB, L_FH4_ReceivedMentalHerb
    h_goto_if_set FLAG_WINGULL_DELIVERED_MAIL, L_FH4_WingullReturned
    h_goto_if_set FLAG_WINGULL_SENT_ON_ERRAND, L_FH4_WingullOnErrand
    h_msgbox T_GoBird                               // There! Go, Bird Pokémon!
    h_closemessage
    h_setflag FLAG_WINGULL_SENT_ON_ERRAND
    h_clearflag FLAG_HIDE_WINGULL_MOSSDEEP_HOUSE
    h_applymovement FH4_WINGULL, Mv_FH4_WingullExit
    h_waitmovement
    h_removeobject FH4_WINGULL, FLAG_HIDE_WINGULL_FORTREE_HOUSE
    h_release
L_FH4_WingullOnErrand:
    h_msgbox T_OnErrand                             // Heheh, I asked my Wingull to run an errand for me.
    h_release
L_FH4_WingullReturned:
    h_msgbox T_Welcome                              // Good! Welcome back, Wingull! ... A Mental Herb? ...
    h_closemessage                                  // (Black 2's item script opens its own window)
    h_giveitem ITEM_MENTAL_HERB
    h_goto_if_eq HLIB_RESULT, 0, L_FH4_BagFull
    h_setflag FLAG_RECEIVED_MENTAL_HERB
    h_release
L_FH4_ReceivedMentalHerb:
    h_msgbox T_FriendsFar                           // Thanks to my Wingull, I have friends who live far away.
    h_release
L_FH4_BagFull:                                      // Common_EventScript_ShowBagIsFull
    h_bag_is_full T_BagFull
    h_release

FH4_Wingull:                                        // FortreeCity_House4_EventScript_Wingull
    c7_mon_cry SPECIES_WINGULL, T_Wingull

    .balign 4, 0
Mv_FH4_WingullExit:                                 // FortreeCity_House4_Movement_WingullExit
    walk_fast_down 2
    walk_fast_right
    walk_in_place_fastest_down
    delay_8
    step_end
